import java.util.Objects;

/**
 * A production-grade immutable key class adhering to the equals/hashCode contract.
 * Using final fields prevents post-insertion mutation bugs.
 */
public final class UserKey {
    private final String username;
    private final int tenantId;
    private final int cachedHash; // Performance optimization for frequently queried keys

    public UserKey(String username, int tenantId) {
        if (username == null) {
            throw new IllegalArgumentException("Username cannot be null");
        }
        this.username = username;
        this.tenantId = tenantId;
        // Pre-compute hash code to keep the key immutable and fast
        this.cachedHash = Objects.hash(username, tenantId);
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        UserKey userKey = (UserKey) o;
        return tenantId == userKey.tenantId && 
               username.equals(userKey.username);
    }

    @Override
    public int hashCode() {
        return cachedHash;
    }
}
